Here is the commit message:
net/mlx5: Fix tainted pointer delete is case of flow rules
 creation fail

In case of flow rule creation fail in mlx5_lag_create_port_sel_table(),
instead of previously created rules, the tainted pointer is deleted
deveral times.
Fix this bug by using correct flow rules pointers.

Found by Linux Verification Center (linuxtesting.org) with SVACE.

Fixes: 352899f384d4 ("net/mlx5: Lag, use buckets in hash mode")
Signed-off-by: Aleksandr Mishin <amishin@t-argos.ru>
Reviewed-by: Jacob Keller <jacob.e.keller@intel.com>
Reviewed-by: Tariq Toukan <tariqt@nvidia.com>
Link: https://lore.kernel.org/r/20240604100552.25201-1-amishin@t-argos.ru
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug was caused by the incorrect handling of flow rule deletion in the event of a failure during flow rule creation. The original implementation used nested `while` loops without properly resetting the inner loop variable, which could lead to the same flow rule pointer being deleted multiple times, resulting in potential memory corruption or crashes.

Here is the patch:

 static int mlx5_lag_create_port_sel_table(struct mlx5_lag *ldev,
 					  struct mlx5_lag_definer *lag_definer,
 					  u8 *ports)
 {
 	struct mlx5_core_dev *dev = ldev->pf[MLX5_LAG_P1].dev;
 	struct mlx5_flow_table_attr ft_attr = {};
 	struct mlx5_flow_destination dest = {};
 	MLX5_DECLARE_FLOW_ACT(flow_act);
 	struct mlx5_flow_namespace *ns;
 	int err, i;
 	int idx;
 	int j;

 	ft_attr.max_fte = ldev->ports * ldev->buckets;
 	ft_attr.level = MLX5_LAG_FT_LEVEL_DEFINER;

 	ns = mlx5_get_flow_namespace(dev, MLX5_FLOW_NAMESPACE_PORT_SEL);
 	if (!ns) {
 		mlx5_core_warn(dev, "Failed to get port selection namespace\n");
 		return -EOPNOTSUPP;
 	}

 	lag_definer->ft = mlx5_create_flow_table(ns, &ft_attr);
 	if (IS_ERR(lag_definer->ft)) {
 		mlx5_core_warn(dev, "Failed to create port selection table\n");
 		return PTR_ERR(lag_definer->ft);
 	}

 	lag_definer->fg = mlx5_create_hash_flow_group(lag_definer->ft,
 						      lag_definer->definer,
 						      ft_attr.max_fte);
 	if (IS_ERR(lag_definer->fg)) {
 		err = PTR_ERR(lag_definer->fg);
 		goto destroy_ft;
 	}

 	dest.type = MLX5_FLOW_DESTINATION_TYPE_UPLINK;
 	dest.vport.flags |= MLX5_FLOW_DEST_VPORT_VHCA_ID;
 	flow_act.flags |= FLOW_ACT_NO_APPEND;
 	for (i = 0; i < ldev->ports; i++) {
 		for (j = 0; j < ldev->buckets; j++) {
 			u8 affinity;

 			idx = i * ldev->buckets + j;
 			affinity = ports[idx];

 			dest.vport.vhca_id = MLX5_CAP_GEN(ldev->pf[affinity - 1].dev,
 							  vhca_id);
 			lag_definer->rules[idx] = mlx5_add_flow_rules(lag_definer->ft,
 								      NULL, &flow_act,
 								      &dest, 1);
 			if (IS_ERR(lag_definer->rules[idx])) {
 				err = PTR_ERR(lag_definer->rules[idx]);
-				while (i--)
-					while (j--)
+				do {
+					while (j--) {
+						idx = i * ldev->buckets + j;
 						mlx5_del_flow_rules(lag_definer->rules[idx]);
+					}
+					j = ldev->buckets;
+				} while (i--);
 				goto destroy_fg;
 			}
 		}
 	}

 	return 0;

 destroy_fg:
 	mlx5_destroy_flow_group(lag_definer->fg);
 destroy_ft:
 	mlx5_destroy_flow_table(lag_definer->ft);
 	return err;
 }



